#!/bin/bash
# 器律⑨: deposit-lane brief renderer for the sshx formalization line (session w72 lineage).
# usage: lane_brief.sh LANE WORKTREE BASESHA LEASE.json EXCL.txt OUT.md [PROBE_NOTE.txt]
#   LEASE.json = list (or {"atoms":[...]}) of digest-status v3 candidate rows: source_id, atom_id, ast_path, kind, atom_text
#   EXCL.txt   = one atom_id per line (see refresh_exclusions.sh)
# Glue, not program (CLAUDE.md 第 11 条辨析): fail-fast on inputs, sentinel line `LANE_BRIEF_OK` on success, idempotent (rewrites OUT).
# The two prompt templates are embedded below (data lives with its only consumer; no .md under tools/).
set -euo pipefail
[ $# -ge 6 ] || { echo "LANE_BRIEF_USAGE: lane_brief.sh LANE WORKTREE BASESHA LEASE.json EXCL.txt OUT.md [PROBE_NOTE]" >&2; exit 64; }
python3 -X utf8 - "$@" <<'PY'
HEAD = r'''# deposit lane brief — LANE (implementation worker, trureturing formalization line)

You are an autonomous formalization deposit worker. Your work target (already prepared, clean, pinned to dev BASESHA):

    WORKTREE

Work ONLY inside this worktree. Never touch /Users/mstudio3/trureturing (main checkout) or any other worktree.

## Environment (export before any repo command)

    export PATH="/opt/homebrew/bin:$HOME/.elan/bin:$HOME/.dotnet:$PATH"
    export DOTNET_ROOT="$HOME/.dotnet"

Slot vars `STRATALINT_LEAN_MAX_CONCURRENCY=8 STRATALINT_LOCK_TIMEOUT_SECONDS=3600` may be set ONLY for `make deposit` / `make lean-report` invocations — NEVER for `make preflight`.

If `tools/**/net10.0/StrataLint` binary is missing, run `make -C tools dotnet` first.


## Your lease (atom 1 = ACTIVE; atoms 2..n = ordered FALLBACK queue used only after an evidence-classified ejection; verbatim atom ids; disjoint from other lanes)
'''
BODY = r'''## Per-atom protocol

1. Branch once for the lane: `git checkout -b lane/math/LANE` (from the pinned dev HEAD BASESHA).
1a. SINGLE-PIECE FLOW (w72 panel convergence, 2026-08-29): atom 1 of your lease is the ACTIVE atom; atoms 2..n are an ORDERED FALLBACK QUEUE. Work the active atom to a terminal state: DEPOSITED (new module) or BOUND (receipt-only bind to a frozen GID) ends the flight after landing (one deposit unit per branch/PR — never author a second module on this branch); an EVIDENCE-CLASSIFIED EJECTION does not end the flight — record it and move to the next fallback atom on the same (still empty) branch. Stop when one deposit/bind has landed or the queue is exhausted.
2a. DEFINITIONAL-SUBSTITUTION BAN (w10 blood case x2): the deposited statement must CONSTRUCT the source's objects from source-semantics primitives (channels, relations, predicates, cost models). DEFINING the source's object to be the structure your theorem concludes (e.g. def fixedAlgebra := range blockDiagonal; def checkWork n := n^2) makes the theorem a tautology about its own definition — that is NOT coverage and will be retracted. 2b. PUBLIC-CLAUSE RULE (w10 blood case): EVERY clause of the atom must appear in the PUBLIC deposited statement; a clause proven only in a private helper does not count. 2c. VACUOUS-CONJUNCT BAN (w16 blood case, receipt retracted): a conjunct that is UNCONDITIONALLY TRUE regardless of the source's content (e.g. a cardinality-product identity that holds for any finite types) covers nothing — each conjunct of your public statement must be falsifiable by some model of the source's primitives; apply tautology_check PER CONJUNCT, not only to the whole. 2c⁶. CANONICAL-OBJECT RULE (w26 blood case, receipt retracted): when the source's claim IS a canonical construction (a specific map/equivalence/decomposition, esp. one the source says needs no choice/section), the public statement must expose THAT object (state the equivalence/map directly, e.g. `X ≃ Σ b, Fiber q b` via the named canonical map with its computation rule) — `Nonempty (…)` inhabitation is under-coverage even when nontrivial. 2c⁷. PRIMITIVE-BEFORE-DEF CHECK (w26 structural case; w41/w44 forks: law defs = conceptLaw/nextReadoutJointLaw/completionLaw, selectedExperimentReadout = jointReadout): before introducing ANY new `def`/`abbrev`, grep the CURRENT tree BY BODY SHAPE as well as by name — e.g. `git grep -n -E 'fun x i => q i x|pushforward \(fun|Quotient \(Setoid.ker' -- D5` for the construction you are about to write — and IMPORT the existing primitive (instantiate it; e.g. `jointReadout (fun i : selected => output i.1)`) instead of redeclaring. A def that is definitionally identical to an existing D5 primitive after unfolding is a FAMILY-SSOT fork and the receipt WILL be retracted (w41q1, w44p1 precedents). Record every such grep in your worklog (pattern + hit/miss). The caller also runs a cross-lane collision check before arming. 2c⁵. CONTRAST-CLAUSE RULE (w25 blood case, receipt retracted): an atom stating "X holds for A but FAILS for general B" has TWO public halves — the positive half AND the failure half (a formalizable countermodel statement, e.g. an explicit topology where the property fails); depositing only the positive half is a public-clause violation. 2c⁗. CONVERSE-PREMISE RULE (w24 blood case, receipt retracted): when the source states an INDEPENDENT converse, forward and reverse conjuncts need DISJOINT premise sets — a conjunct must never conclude (or trivially follow from) a theorem-wide hypothesis; check per conjunct that its conclusion is not among the global premises. 2c‴. NONEMPTY-WRAPPING BAN (w22 blood case, receipt retracted): stating a public conjunct as `Nonempty (SomeWitnessStructure …)` is vacuous — such types are inhabited by trivial witnesses for ANY carrier; the property must be stated DIRECTLY on the named relation/object (e.g. reflexivity and transitivity of the named refinement relation, quantified publicly), never hidden inside a witness structure behind Nonempty. 2c′. QUALITATIVE-REMARK RULE (w20 blood case, receipt retracted): a source clause that is qualitative/hedged (通常/往往/typically/usually) with NO in-scope definition is NOT formalizable as a universal conjunct — if the atom's NAMED (boxed) theorem excludes the remark, deposit the formal statement only; otherwise eject statement-unformalizable quoting the remark. NEVER invent a definition to make the remark provable. 2c″. CARRIER-FIDELITY RULE (w20 blood case, receipt retracted; 3rd carrier defect): your PUBLIC objects must live on the source's EXACT carrier — same scalar field, same subspace (e.g. real Herm_d^0, not complex full matrix algebra); a proof routed through a different carrier needs an explicit public bridge back to the source carrier, else it is drift. 2d′. FAMILY-SSOT RULE (w17 arch finding): when your module extends or redoes content in an EXISTING D5 family, IMPORT the family's canonical types (or the frozen predecessor's) — never redeclare sibling-namespace copies of runtime/observation/closure types; a fork of the family's single source of truth is a material defect. 2d. UNIQUENESS FIDELITY (w16 blood case, receipt retracted): when the source demands a UNIQUE object (unique descent/factorization/representative), plain ∃ is under-coverage — state ∃! (or ∃ + an explicit public uniqueness clause).
2. Eligibility: `dotnet run --project tools/StrataLint.Cli/StrataLint.Cli.csproj --configuration Release -- show-atom --atom-id <atom_id>` — read the atom text. Deposit unit = the atom's NAMED theorem: conjuncts are formalized WHOLE via ∧. Do NOT reject for multi-clause shape (partial/casework decomposition is legal only when the ledger atom itself is single-clause). Do NOT deposit a special-case instantiation as coverage of a general atom (the atom stays open in that case — record `statement-unformalizable` ONLY with the quoted clause that resists formalization).
2d′. PRE-BIND WHOLE-ATOM CLAUSE CHECK (w72a1 blood case 2026-08-29, PR #4060 rejected by all three pre-merge seats): a bind is legal ONLY if EVERY clause of the atom — boxed statements AND the mathematical consequences stated in its 解释/说明 paragraphs, and every `/clause/N` child atom the ledger lists under the same ast_path — is a PUBLIC part of the frozen theorem. A frozen theorem that states one or two of the atom's clauses is NOT an exact hit: deposit a NEW module that imports it and adds the missing public clauses (or eject). Before any bind, write the clause_matrix against the FROZEN statement and confirm zero missing rows; `git ls-files Meta/Digestion/backfill/*/residual-open | grep <ast_path prefix>` shows the child clause atoms that would remain open.
2d″. WITHDRAWN-RECEIPT REBIND BAN (w72c1 blood case 2026-08-29, PR #4059 rejected): before binding atom A to frozen GID X run `git log --format='%h %s' origin/dev -- Meta/Digestion/formalizations/<A>.v1.json`; if an `errata:`/withdraw commit removed a receipt naming X (or any predecessor of X), that binding was ALREADY adjudicated hollow — 一事不再理 — never re-bind it; treat X as under-coverage and either deposit a corrected module or eject citing the errata commit.
2e′. EXACT D5 HIT = BIND, NOT WRAP (w43/w44 recurrence; #3040 precedent): if an EXISTING frozen D5 theorem already states the atom's NAMED theorem on the source carrier (same clauses, same generality), do NOT author a wrapper module — run `make deposit ATOM_ID=<id> GID=<existing gid> BASE=BASESHA` so the receipt BINDS the atom to the existing declaration (receipt-only commit, zero Lean diff), and record `bind_only: true` in the envelope atom entry. A thin wrapper module restating a D5 theorem is an SSOT duplicate (the same statement under two GIDs) — the mathlib-first 'thinnest honest wrapper' rule applies ONLY to Mathlib hits (a receipt cannot bind to Mathlib). If the existing theorem covers only a special case or lacks a clause, that is NOT an exact hit: deposit a new module that IMPORTS and applies it. TFAE PROJECTION (w49 errata): if the atom is an iff/implication between two clauses of a frozen `List.TFAE` theorem, `(thm …).out i j` is a projection wrapper — BIND the atom to the TFAE theorem instead of depositing the projection.
3. Mathlib-first search (formalization hand may search; judging gate stays offline): loogle/leansearch/local mathlib grep. Record an exact hit/miss trail (what name, where searched, hit or miss) in your worklog and envelope notes. Any exact hit MUST be directly applied (import + apply, thinnest honest wrapper) — never re-prove.
4. Author the Lean module: route a manifest first — ROUTE-MANIFEST HYGIENE (2 CI failures taught this): write the manifest file OUTSIDE the repo tree (e.g. /private/tmp/<lane>-route.yaml), never at repo root, and NEVER commit it (SL-000 unknown top-level artifact + SL-003 root overflow) (`-- route <manifest>` gives the canonical path + skeleton), F-plane six-line header copied byte-exact in shape from a green D5 module (SL-012: header at byte zero). CamelCase modules/types, snake_case theorems. Zero `sorry`. Axiom closure of every new declaration exactly {propext, Classical.choice, Quot.sound}. `anchors: []` unless a registered anchor exists (SL-017). NO theory acronyms anywhere in .lean/.scribe.cs content (TheoryIsolation is case-insensitive — no "PZG", "GICT", "QDO" etc. in identifiers, comments, or prose). SCRIBE LATEX ROW-SEPARATOR (w16 CI failure x2): the formula emitter consumes '[' immediately after a LaTeX row separator as a row-spacing optional argument — put an empty group between them.
4c. SCRIBE SELF-TEST (machine gate, not prose — w40 recurrence of the stray-Id class despite the 2e ban proved prose decays): after `make emit`, ALWAYS run
   dotnet test tools/tests/StrataLint.Scribe.Tests/StrataLint.Scribe.Tests.csproj --configuration Release --filter "FormulaTests|FormulaCorpusInventoryTests"
   (fast, seconds) and fix any red BEFORE preflight. Record the verbatim exit in your envelope as scribe_selftest_exit.
4b. PRE-DEPOSIT HYGIENE (w39 reflection — three recurring CI classes, one clause each):
   - PLANE CHECK (SL-010, 2 cases): before `make deposit`, verify your header `generality:` matches the planes of your imports (grep a green sibling importing the same facts; G must not import I facts).
   - BUCKET CHECK (SL-003, 3 cases incl. w71q2 2026-08-27): before routing into an EXISTING family directory, count on ORIGIN/DEV after a fresh fetch — `git fetch origin dev && git ls-tree origin/dev --name-only D5/<family>/ | grep -c '\.lean$'` (NOT `ls` on your pinned tree: dev advances while you work and the admission check judges the UNION) — if >= 24, route to a sibling split bucket instead (只裂不迁); repeat the same count immediately before push and re-route if it became 24 meanwhile.
   - NAME-WORD CHECK (SL-019 word-scan false positive, issue #2989): module names must not contain the substrings failure/exception/tension/anomal (case-insensitive) — the receipt anomaly scanner fires on them regardless of content; pick a synonym (inexactness/breakdown-free phrasing).
   - REDO RECEIPT HYGIENE (w53p2, three receipts with a stale primary_gid): before depositing a REDO atom, check `Meta/Digestion/formalizations/<atom_id>.v1.json` on your base — if it EXISTS (old receipt not yet withdrawn on your base, or the atom was bound to another GID), `git rm` it in its own commit FIRST; otherwise `make deposit` MODIFIES the old receipt, keeps the old `primary_gid`, and files your new module only under `hosted_extensions`. After the deposit, `grep primary_gid` on the receipt and confirm it names YOUR new GID.
   - NO UNUSED PREMISES (w52 review, PredictionDecisionSufficiency withdrawn): never add a hypothesis the source does not state; after the proof compiles, delete every hypothesis Lean reports unused (an `_`-prefixed binder is a confession) — an unused premise is an avoidable loss of generality and fails "full generality".
   - PRE-PUSH MERGE CHECK (w53p2, #3175 DIRTY): before `make pr-open`, run `git fetch origin dev && git merge-tree origin/dev HEAD | grep -c CONFLICT`; if nonzero, `git merge --no-edit origin/dev` and resolve — for a MODIFY/DELETE on one of YOUR redo receipts (dev deleted the old receipt via an errata while you rebound it) keep OURS (`git add <receipt>`); for anything else STOP and report. Never rebase.
   - EMPIRICAL REMARKS (w51 ruling): a source clause tagged `实测`/`[机验]`/`数值` (a measured band, a fitted exponent, a run count) is an empirical observation, not a theorem clause — do not formalize it and do not count its absence as a defect; DISCLOSE it in the receipt notes as "empirical remark outside the named theorem" so reviewers see it was seen.
   - NEW-DEF FORK CHECK BY BODY SHAPE (w51 review, two withdrawals): before writing ANY `def`/`abbrev`, grep D5 for the canonical primitive with the same body shape — e.g. `∀ k, q (τ^[k] y) = q (τ^[k] y')` IS `completeItinerary τ q y = completeItinerary τ q y'`; `s a + s b - s (a + b)` IS `sectionCarry s a b`; `{p | r p.1 = r p.2 ∧ t p.1 ≠ t p.2}` IS `defectRelation r t`; `fun i => output i` bundles ARE `jointReadout`. Reference the primitive (`:=` or import) instead of restating its body; a restated body is a fork even when the theorem is new.
   - INDEPENDENCE IS A JOINT LAW (w50 review, ExternalizedCertificationMeaning withdrawn): "independently sampled" / "i.i.d." must be a product or joint distribution on the tuple type (`PMF (Fin m → α)`, `Measure.pi`, or an explicit product law) — NEVER a family of per-coordinate marginals with "all marginals equal", and never a hand-multiplied mass; the D5 `independent_sampling_exponential_bound` family already supplies the product-law step. A carrier of the form `(Fin m → PMF α) × (Fin m → α)` cannot express independence.
   - NO NEW SIBLING BUCKET WHILE THE FAMILY BUCKET HAS ROOM (第8条 桶满则裂, w51o1 ExperimentDesign beside Experiment=7): route a new module into the EXISTING family directory unless `ls` shows it already holds 24 Lean files; a fresh directory is allowed only at bucket overflow (只裂不迁) or when no family directory exists at all. Name-similar siblings (Experiment / ExperimentDesign, Coding / ResidueCoding) count as the same family.
   - SEPARABLE COUNTERMODEL BAN (w49 review, #3142 two withdrawals): in an existential countermodel `∃ x y …, P ∧ ¬Q`, every positive conjunct must SHARE its construction with the negative one — if a positive conjunct is discharged by choosing its own witness (`judgment := target` then `rfl`) and its variables never occur in the negative clause, it is separable and vacuous; the theorem then only says ¬Q. Tie the positive side to the same objects the negative side is about (define the outcome from the procedure whose certificate fails), or state the negative clause alone under its true source name.
   - NO REBASE, EVER (w49x1, #3138 SL-008 ×3): Freeze shards anchor COMMIT SHAs; `git rebase origin/dev` (or any history rewrite) orphans every anchor on the branch and CI rejects all of them. If you need a fresher base, `git merge --no-edit origin/dev` (merge commits are fine); never rebase, amend, or reset. If a local `make preflight` reports "SL-008 … Freeze-anchor ancestry" or "not a reachable commit", that is the rebase/amend symptom — do NOT push; report it verbatim.
   - POST-FREEZE LEAN EDIT (w47p1 repair class, #3112 SL-008): if you must change a Lean file AFTER its Freeze shard was recorded on this branch (header fix, linter fix), there is NO ledger-sync verb in the CLI registry (checked 2026-08-29), so no Reattest can be appended — the admission judge recomputes the Freeze material from the tree blob and a candidate-side Reattest does not cure a candidate-side Freeze on a vanished blob. Instead: new commit that `git rm`s that module's branch-added Freeze shard + receipt (both absent from origin/dev), then re-run `make deposit ATOM_ID=… GID=<same gid> BASE=BASESHA` on the corrected blob. Never amend the earlier commits.
   - PROJECTION PIN (w44 repair class, precedent 1747c1426 / 2bd3ce6eb): if preflight reds on `TruthReleaseCommandTests.CommandProducesAndVerifiesAllSevenArtifactsEndToEnd` because the reportless pinned projection fixture lacks your theorem's `FromLean()` statement, the established repair is a NEW forward commit adding the exact live statement-v1 tuple to `Golden/Projection/statement-projection-expansion-v1.json` (Golden data under the strict loader; nothing under tools/). Never amend the deposit/Freeze commits. HYPOTHESIS PARITY (w45 errata, DistinctPrimeFactorCountBound): every hypothesis in the Lean theorem signature (e.g. `(hd : d ≠ 0)`, nonemptiness, finiteness, surjectivity) MUST appear as a displayed premise in the Scribe formula; a displayed statement that omits a Lean hypothesis is FALSE on the admitted inputs the hypothesis excludes. CARRIER/INSTANCE BINDERS COUNT TOO (w47 review: 4 modules rejected for omitting `RCLike K`, `FiniteDimensional`, `Fintype`, `[Finite G]`, or leaving a topology identifier free instead of `partitionTopology(C)`) — the repository convention is `Blueprint/D5/S3/Observer/Linear/DiscountedObservabilityGramianPositivity.scribe.cs:68-73` (`∀ K,V,Y,…, RCLike(K) ∧ FiniteDimensional(K,V) ∧ … ⇒ …`); never hide a clause behind an opaque label like `FinitePGroupFactors()`. Before `make deposit`, list the Lean binders and check each one off against the scribe.cs formula.
   - SCRIBE CORPUS (w38/w39, 5 cases): before writing any Power/Subscript formula shape, READ tools/tests/StrataLint.Scribe.Tests/Projection/RendererCorpusContractTests.cs (~lines 380-420) and use ONLY child-kind pairs the corpus constructs; never guess.
5. RECYCLED-TREE REPORT (2026-08-28 w71rebind blood case, #3671 empty PR): this worktree is RECYCLED — run `make lean-report` (slot vars allowed) ONCE before the first `make deposit`; a stale cached report makes the deposit door refuse with 'unknown module'. If `.lake/build/stratalint/raw-lean-report.json` is newer than every `.lean` you touched, one run suffices.
5. Build: **FIRST Lean action on this lane MUST be `make lean-cache-ensure`** (cold-open raw lake is BANNED — CLAUDE.md 器律③, issue #2762: a raw lake command on a stampless tree forfeits donor clonefile seeding and costs a 3h+ full content-layer rebuild). Then build via `make lean` (or targeted `lake build <Module>` ONLY after ensure reported present/seeded on this tree) until green. No numeric iteration cutoff — eject only on an evidence-classified blocker:
   - `missing-prerequisite`: record the exact missing lemma + full search trail, then CONTINUE to the next lease atom (never early-stop the lane).
   - `statement-unformalizable`: quote the exact resisting clause.
   - `same-atom-already-on-dev`: verify via grep/census, record, continue (一事不再理).
   - `statement-defect` (IN-SCOPE-CONTEXT RULE, w14 blood case: a false-defect claim ignored the source's local deterministic definition): before claiming ANY source defect you MUST read and QUOTE the source's in-scope definitions/hypotheses (the paragraphs immediately preceding the theorem); a counterexample that violates an in-scope definition is INVALID and a false claim here defames a healthy atom.
  Original class text: a clause of the atom is PROVEN FALSE or defective at source level (cite the in-repo proving declaration or give an explicit counterexample). May be combined with another class (e.g. `statement-defect+missing-prerequisite`).
   Nothing else is an ejection class. Effort count is never a reason.
   HONESTY RULE (wave-4 review precedent): if during eligibility/search you learn of ANY known source-level defect, domain restriction, or in-repo refutation touching the atom (e.g. a frozen module docstring recording a clause is false at some parameter), you MUST record it in the envelope notes even when the primary ejection class is something else. Omitting a known defect from the published record is a review-blocking violation. The known_source_defects field in the envelope is the REQUIRED structured carrier for this rule — prose notes alone do not satisfy it. Two waves produced two blocking review findings of exactly this omission shape; the field exists because prose rules did not hold.
5b. FREEZE-ANCHOR RULE (3 CI failures taught this): after `make deposit` has generated Freeze shards, NEVER amend, rebase, or rewrite any commit — the shards anchor the exact commit SHAs. If you must change bytes afterwards, make a NEW commit and re-derive the affected Freeze canonically; verify every anchor with `git cat-file -t <sha>` (exit 0) before pushing.
6. Deposit: `make deposit ATOM_ID=<id> GID=<gid> BASE=BASESHA` — then grep-verify the atom id appears in the produced digestion record. Commit promptly after each successful deposit (small commits).
7. After the lease is exhausted (all atoms deposited or evidence-ejected):
   - If ZERO deposits: do NOT push, do NOT open a PR. Record the ejections in the envelope and finish.
   - Else: FULL BUILD CHECK: `make lean` on the whole project must exit 0 (record `full_lean_build_exit`); Scribe self-test (4c) exit 0 (record `scribe_selftest_exit`); PRE-PUSH MERGE CHECK (below) = 0 conflicts. `make preflight` is NOT required (CLAUDE.md 器律② 2026-08-26: CI's three required checks are the sole admission authority); run it ONLY to diagnose a red on your own PR, and if you do, record the verbatim exit.
   - Push: `env -u GH_TOKEN -u GITHUB_TOKEN git push origin lane/math/LANE`
   - Open PR: write a PR message file OUTSIDE the repo tree at /private/tmp/LANE-pr-message.txt (NEVER commit it): line 1 = concise theorem-scope title; then a blank line; then a body that carries the 产地三项 (CLAUDE.md 9′): `Skill: consensus-rnd:sshx deposit lane LANE (implementation worker)`, `Carrier: codex-cli implementation seat (lane LANE) authored the Lean module + Scribe + deposit; orchestrator (claude main loop) cut the lease and lands; review = PRE-MERGE codex-cli triplet (architecture/quality/tests) dispatched by the orchestrator — PENDING at PR open, outcome appended by the orchestrator before arming (single carrier family, no model-diversity claim)`, `Mixing: blind parallel lanes; CI three required checks are the sole admission authority`, plus one line per atom (atom_id prefix -> GID or ejection class). Then run `make pr-open HEAD=lane/math/LANE MESSAGE=/private/tmp/LANE-pr-message.txt` WITHOUT AUTO_MERGE (one foreground command; it creates the PR and waits for the required-CI verdict) — record the VERBATIM exit code and the PR number (from output `pr=N`, else `gh pr list --head lane/math/LANE`). Do NOT arm auto-merge and do NOT run `gh pr merge`: the orchestrator runs a PRE-MERGE review triplet (architecture / quality / tests) on this tree and arms auto-merge only after it passes.
8. Worklog: keep an append-only worklog file inside the runner attempt dir alongside result.json (same directory), named worklog.md. Reference it as log_ref.

## Envelope conclusion schema (write result.json per the runner's appended envelope instructions)

conclusion = {
  "verdict": "<stage verdict per runner instructions>",
  "lane": "LANE",
  "branch": "lane/math/LANE",
  "base": "BASESHA",
  "atoms": [
    {"atom_id": "...", "outcome": "deposited|ejected", "ejection_class": null|"missing-prerequisite"|"statement-unformalizable"|"same-atom-already-on-dev"|"statement-defect"|"<compound with +>", "gid": "...", "mathlib_trail": "compact hit/miss summary", "lean_build_exit": 0, "deposit_exit": 0, "encoded_scope_hypotheses": ["REQUIRED: every source restriction you learned that IS encoded as a hypothesis of the deposited statement (finiteness, metric/Lipschitz setup, domain bounds). Benign but mandatory; empty [] = explicit claim none were learned."], "known_source_defects": ["REQUIRED: every learned restriction, endpoint failure, falsity, in-repo refutation, or proof hole that is NOT captured by the deposit or blocks the atom (e.g. 'frozen X.lean:36 requires 0<N<4; atom states no bounds; undefined at N=0,4'). Empty [] = explicit claim none were learned. A reviewer finding one you knew (worklog, cited module) in EITHER field's scope is a blocking violation."], "notes": "..."}
  ],
  "full_lean_build_exit": <verbatim>, "scribe_selftest_exit": <verbatim>, "merge_tree_conflict_count": <n>, "preflight_exits": [..only if run..], "door_closed": false|true, "door_error": null|"verbatim",
  "pr": {"number": N|null, "pr_open_exit": <verbatim>},
  "reasoning_discipline_note": "reference frame; known-good shape; 美不美 verdict w/ specific defect or 'no material defect found'; ASSUMED-UNVERIFIED items",
  "visible_inputs_disclosure": "repo-prior-exposed (CLAUDE.md/AGENTS.md inherited; uncontrolled)"
}

MANDATORY TAUTOLOGY SELF-CHECK (w12 blood cases x3 — prose bans failed, so this is now a REQUIRED envelope field): for EVERY deposited theorem add "clause_matrix": [{"clause": 1, "source_excerpt": "verbatim words of the source clause", "lean_conjunct": "the public conjunct/binder that states it", "premises": ["hypotheses this conjunct depends on"]}] (REQUIRED per deposited/bound atom: every numbered source clause maps to a PUBLIC part of the primary Lean statement; a clause with no row is a coverage gap you must eject on), "tautology_check": {"conjuncts": N, "conclusion_in_hypotheses": false, "objects_constructed_not_defined_as_target": true, "least/extremal_properties_taken_from_source_test_not_goal": true} — set honestly per conjunct; a reviewer falsifying any entry is an automatic retraction. Specifically (w46 blood case: a `let admitted := {s | target s = false}` example block published `∀ s, s ∈ admitted ↔ target s = false`, which is `P ↔ P` by rfl — the receipt was retracted): the check applies to EVERY conjunct at EVERY nesting depth, unfolding `let`-bindings inside example/contrast blocks; an equivalence or equation whose one side is the let-definition of the other is a vacuous conjunct; (a) no conjunct's conclusion may appear among its hypotheses; (b) no source object may be DEFINED as the structure the theorem concludes; (c) Nat.find/extremal definitions must use the SOURCE's test (e.g. R_m = R_{m+1}), never the goal property.

Real exit codes only — capture `$?` of the command itself, never of a pipe tail. No fabricated greens: report what ran and its exit. Unverified claims must be marked ASSUMED-UNVERIFIED.

NO LAUNDERING OF UNUSED HYPOTHESES (w58 blood case, ConditionalIndependentInformationSubmodularity.lean:320-321): a source premise you cannot use must stay an honest unused binder (or be dropped if the theorem is strictly stronger without it) — NEVER `have scope := ⟨h1, h2⟩; clear scope` or any other construction whose only purpose is to silence the unused-variable linter. The review reads the proof; a laundered premise is reported as a defect on top of the unused premise.
NO DEFINITIONAL RESTATEMENT (w58 blood case, MonotoneOptionValue: `(valueMonotone : Monotone value) … := by exact valueMonotone optionInclusion`): if the whole proof is one application of an imported definitional hypothesis (Monotone, Function.FactorsThrough, Set.Subset, …) to a binder, the theorem has no content — construct the source object (the value, the projection, the readout) from source primitives and PROVE the property, or eject as definitional-in-canonical-encoding with an exact trail.

KILLED PREFLIGHT IS NOT GREEN (w59f1 blood case: `make preflight` terminated with exit 143 mid test-stream, worker pushed anyway): exit 143/137/124 or any "terminated" preflight is NOT a green and NOT a listed flake. Run `make preflight` so it cannot be killed by your own tool timeout (a single long-running foreground command with its exit code captured to a file, e.g. `make preflight > /private/tmp/<lane>-preflight.log 2>&1; echo EXIT=$? >> /private/tmp/<lane>-preflight.log`, and wait for the file's EXIT line); if it was killed, re-run it once; if it is killed again, do NOT push — report the verbatim exit and the log path.

BUCKET ROUTING IS A CHECKED STEP, NOT A GUESS (SL-003 DirectoryFileLimit is 24 since 2026-08-30 #4045; tolerance 48) (w59 + w61 blood cases: SIX premature sibling buckets in two waves — EpistemicRefinement, InterventionLaws, InterventionBounds, ExperimentBoundary, History, SequentialDecisionRisk — every one created while a sibling with room existed; each cost a withdrawal + placement redo). BEFORE `route`, for every new module run and RECORD in the envelope (`routing_check`): `for d in $(git ls-tree origin/dev --name-only D5/S3/<Family>/ | grep -v '\.lean$'); do echo "$d $(git ls-tree origin/dev --name-only $d/ | grep -c '\.lean$')"; done` — then choose, in this order: (1) the semantically matching EXISTING bucket with < 24 files; (2) if the matching bucket is full (= 24 or more), the closest EXISTING sibling with room; (3) a FRESH sibling ONLY when the family bucket AND every semantically adjacent sibling is at 24+ — and say so in `routing_check` naming the full siblings and their counts. A new one-file bucket next to a sibling that had room is a placement defect on review, regardless of how well the name fits.

ROUTING_CHECK IS NOT OPTIONAL (2026-08-26, second omission after w64p2/w66c1): an envelope whose conclusion lacks a non-null `routing_check` (one entry per deposited atom: target bucket, `git ls-tree origin/dev` count of that bucket and of its parent/adjacent siblings, and the rule applied) is INCOMPLETE — the caller will not chain the lane on it and will send a retry attempt. Write it before `make deposit`, from the counts you actually ran.

REDO SHAPE (2026-08-26, w65 review 2/3 + SHA evidence): a redo whose predecessor is FROZEN (receipt withdrawn, Lean immutable) must NOT reprove or copy the theorem — that leaves two frozen owners of one elaborated theorem (FAMILY-SSOT fork). The settled shape is: new module in the correct bucket, `import` the frozen predecessor, state the theorem on the canonical primitives, prove by `exact <frozen predecessor>` (a preceding `change` ONLY when the stated goal differs syntactically from the frozen theorem's type; for a byte-identical statement a bare single `exact` IS the settled shape — 2026-08-26 caller ruling after the w70 review flagged the absent no-op `change`). Only a redo that CHANGES the statement (removed premise, family-indexed carrier, missing clause added) carries its own proof.

INFRASTRUCTURE CRASH IS NOT A RESULT (2026-08-26, w68errata): if `make preflight` (or any build/test step) dies with `Segmentation fault: 11` / SIGSEGV / an aborted `dotnet restore`, that exit is an infrastructure crash, not a red: re-run the same command once and judge the re-run. Report both exits verbatim. Do NOT withhold a push on the crash alone; withhold only if the re-run is red for a content reason.

PRE-BIND SCRIBE PARITY CHECK (2026-08-26; 4 of the last 5 review-found defects were binder/definiens parity on PRE-EXISTING bind targets: KernelStrictness, CompatibleFusionEmbedding, CodeLedgerIdentity, CofinalTailDiscipline): before writing a receipt-only bind to an existing frozen theorem, open its `Blueprint/**/<Module>.scribe.cs` and compare the displayed proposition against the Lean signature binder-for-binder: every Lean binder (implicit type parameters, instance arguments, hypotheses, let-definiens) must appear typed in the formula; an untyped free identifier, a missing binder, or a `let` replaced by a bare symbol is a projection defect. If the projection is defective, STILL bind (the theorem is correct) but report it in the envelope under `scribe_parity_findings` (gid, file:line, what is missing) so the caller can repair the projection in the same wave's errata instead of a review seat finding it a wave later. A deposit of a NEW module must of course display all its own binders.

TEST THE MERGE TREE, NOT THE BRANCH HEAD (2026-08-26, #3343 attempts 1-5 vs 6): CI judges merge(dev_tip, head) (CLAUDE.md 第19条: refs/pull/N/merge). A local preflight on the unmerged branch head can be green while CI is red whenever dev moved under you. Before the final preflight of any harness/engine change: `git fetch origin dev && git merge --no-edit origin/dev` (a merge commit, never a rebase), then `CI=true make preflight` on the merged tree.

PRE-BIND OWNER CHECK (2026-08-26, w70 TerminalLedgerPartition): before binding to an existing frozen theorem, read its PROOF: if the proof is a single `exact <other frozen theorem> …` (a proposition-identical forwarding wrapper), the SSOT owner is that other theorem — bind THAT GID instead (after its own parity check). Report in the envelope which owner you bound and why.

NO SELF-FLAGGED RECEIPTS (2026-08-26, w71v1 MacroInterventionCriterion): if your own audit concludes a bind or deposit is under-general / not admissible, do NOT write or keep its receipt — eject the atom with the defect as the trail (or deposit the corrected statement). An envelope that says 'do not admit' next to a written receipt is a contradiction the caller must undo before landing.

BIND DOOR (2026-08-26, w71v2 tool error): a receipt-only bind to an EXISTING frozen GID is written by `make deposit ATOM_ID=<atom> GID=<frozen gid> BASE=BASESHA` (the deposit command detects the frozen GID and writes only the receipt). `make cover` is NOT the bind path: it aligns/covers an atom that already has a receipt and fails closed with `COVER_INVALID … formalization receipt is missing` otherwise.
'''

import json,sys,subprocess,collections,os
lane,wt,base,leasef,exclf,out=sys.argv[1:7]
probe=open(sys.argv[7],encoding='utf-8').read() if len(sys.argv)>7 else ''
for p,what in ((wt,'WORKTREE'),(leasef,'LEASE'),(exclf,'EXCL')):
    assert os.path.exists(p), f'LANE_BRIEF_MISSING_{what}={p}'
assert len(base)>=7 and all(c in '0123456789abcdef' for c in base), f'LANE_BRIEF_BAD_BASESHA={base}'
head=HEAD.replace('LANE',lane).replace('WORKTREE',wt).replace('BASESHA',base)
body=BODY.replace('LANE',lane).replace('BASESHA',base)
lease=json.load(open(leasef,encoding='utf-8')); lease=lease.get('atoms',lease) if isinstance(lease,dict) else lease
assert lease, 'LANE_BRIEF_EMPTY_LEASE'
parts=[head.rstrip('\n'),'']
for i,a in enumerate(lease,1):
    parts.append(f"{i}. atom_id: {a['atom_id']}\n   source: {a['source_id']}  ast_path: {a['ast_path']}  kind: {a['kind']}\n   atom_text:\n---\n{a['atom_text']}\n---")
if probe: parts.append('\n>>> '+probe.strip()+'\n')
subprocess.run(['git','-C',wt,'fetch','-q','origin','dev'],check=True)
cnt=collections.Counter()
for path in subprocess.run(['git','-C',wt,'ls-tree','-r','--name-only','origin/dev','--','D5/'],capture_output=True,text=True,check=True).stdout.split():
    if path.endswith('.lean'): cnt[path.rsplit('/',1)[0]]+=1
openadd=collections.Counter()
try:
    prs=json.loads(subprocess.run(['env','-u','GH_TOKEN','-u','GITHUB_TOKEN','gh','pr','list','--state','open','--limit','100','--json','number,headRefName'],capture_output=True,text=True).stdout or '[]')
    assert len(prs)<100, 'LANE_BRIEF_OPEN_PR_LIST_TRUNCATED'
    for pr in prs:
        br=pr['headRefName']; subprocess.run(['git','-C',wt,'fetch','-q','origin',br],capture_output=True)
        added=subprocess.run(['git','-C',wt,'diff','--name-only','--diff-filter=A','origin/dev',f'origin/{br}','--','D5/'],capture_output=True,text=True).stdout.split()
        for path in added:
            if path.endswith('.lean'): openadd[path.rsplit('/',1)[0]]+=1
except Exception as e:
    openadd=collections.Counter(); print('open-PR census skipped:', e, file=sys.stderr)
for d,n in openadd.items(): cnt[d]+=n
full=sorted((d,n) for d,n in cnt.items() if n>=20 and d.startswith('D5/'))
parts.append('\nBUCKETS AT OR NEAR THE ADMISSION LIMIT ON origin/dev RIGHT NOW (limit 24; = origin/dev count PLUS modules added by currently OPEN PRs (they may land before you); computed at brief time - RE-CHECK against a fresh `git fetch origin dev && git ls-tree origin/dev --name-only <dir>/ | wc -l` immediately before `make deposit` AND again before push; your pinned tree is NOT the union): '+'; '.join(f'{d}={n}' for d,n in full)+' -- a new module must NOT go into any directory whose union count would exceed 24 after ALL of your additions; at 24 never add; at 20-23 add at most (24 - listed count) modules there and prefer the semantically matching sibling with room when in doubt.\n')
own={a['atom_id'] for a in lease}
excl=[l.strip() for l in open(exclf,encoding='utf-8') if l.strip() and l.strip() not in own]
parts.append('\nIn-flight exclusions (atoms other lanes hold or open PRs cover - do NOT take):\n\n'+'\n'.join(excl)+'\n')
parts.append(body)
txt='\n'.join(parts)
for a in lease: assert a['atom_text'] in txt and a['atom_id'] in txt, 'LANE_BRIEF_BYTE_FIDELITY'
for tok in ('LANE','WORKTREE','BASESHA'): assert tok not in txt, f'LANE_BRIEF_UNSUBSTITUTED_{tok}'
open(out,'w',encoding='utf-8').write(txt)
print(f'LANE_BRIEF_OK out={out} bytes={len(txt)} atoms={len(lease)} excl={len(excl)}')

